from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class TasksAddResultsSchema(pydantic.BaseModel):
    taskId: str


class TasksAddResponseSchema(BaseRapiResponseSchema):
    results: TasksAddResultsSchema


class TasksEditResponseSchema(BaseRapiResponseSchema): ...


class Task(pydantic.BaseModel):
    taskId: str
    title: str
    creator: str
    assignee: str
    createTime: int
    endTime: int
    lastChange: int
    status: str
    priority: str
    label: str
    tags: Optional[list[str]]
    allowedStatuses: list[str]
    threadId: str
    isRead: bool


class TasksListResultsSchema(pydantic.BaseModel):
    cursor: Optional[str]
    tasks: Optional[list[Task]]


class TasksListResponseSchema(BaseRapiResponseSchema):
    results: TasksListResultsSchema


class Deadline(pydantic.BaseModel):
    type: str
    predefined: str


class Filter(pydantic.BaseModel):
    id: str
    name: str
    order: int
    assignees: Optional[list[str]]
    creators: Optional[list[str]]
    statuses: Optional[list[str]]
    priorities: Optional[list[str]]
    tags: Optional[list[str]]
    labels: Optional[list[str]]
    deadline: Optional[dict]
    subscribed: Optional[bool]
    withChanges: Optional[bool]


class TasksFiltersListResultsSchema(pydantic.BaseModel):
    filters: list[Filter]


class TasksFiltersListResponseSchema(BaseRapiResponseSchema):
    results: TasksFiltersListResultsSchema


class TasksFiltersAddResultsSchema(pydantic.BaseModel):
    id: str


class TasksFiltersAddResponseSchema(BaseRapiResponseSchema):
    results: TasksFiltersAddResultsSchema


class TasksFiltersEditResponseSchema(BaseRapiResponseSchema): ...


class TasksFiltersDeleteResponseSchema(BaseRapiResponseSchema): ...


class TasksFiltersReorderResponseSchema(BaseRapiResponseSchema): ...


class DefaultNotification(pydantic.BaseModel):
    duration: int
    enabled: bool


class TasksNotificationsListResultsSchema(pydantic.BaseModel):
    customNotifications: list[int]
    defaultNotifications: list[DefaultNotification]


class TasksNotificationsListResponseSchema(BaseRapiResponseSchema):
    results: TasksNotificationsListResultsSchema


class TasksNotificationsCustomAddResponseSchema(BaseRapiResponseSchema): ...


class TasksNotificationsCustomDeleteResponseSchema(BaseRapiResponseSchema): ...


class TasksNotificationsDefaultUpdateResponseSchema(BaseRapiResponseSchema): ...


class TasksSetReadResponseSchema(BaseRapiResponseSchema): ...


class TasksGetUserTagsResultsSchema(pydantic.BaseModel):
    cursor: Optional[str]
    tags: list[str]


class TasksGetUserTagsResponseSchema(BaseRapiResponseSchema):
    results: TasksListResultsSchema


class TasksSearchUserTagsResponseSchema(TasksGetUserTagsResponseSchema): ...


class Chat(pydantic.BaseModel):
    sender: str


class Message(pydantic.BaseModel):
    msgId: int
    time: int
    reqId: str
    chat: Chat
    outgoing: bool
    text: str


class Entry(pydantic.BaseModel):
    message: Message
    olderMsgId: int
    newerMsgId: int
    highlight: list[str]


class MonthlyHistogramItem(pydantic.BaseModel):
    entryCount: int
    month: str


class Thread(pydantic.BaseModel):
    entries: list[Entry]
    exhausted: bool
    cursorOne: str
    entryCount: int
    monthlyHistogram: list[MonthlyHistogramItem]


class FoundTask(pydantic.BaseModel):
    foundInTitle: bool
    foundInTags: bool
    foundInThread: bool
    task: Task
    thread: Optional[Thread] = None


class Person(pydantic.BaseModel):
    sn: str
    firstName: str
    middleName: Optional[str]
    lastName: str
    friendly: str


class TasksSearchResultsSchema(pydantic.BaseModel):
    cursor: Optional[str]
    foundTasks: list[FoundTask]
    persons: list[Person]


class TasksSearchResponseSchema(BaseRapiResponseSchema):
    results: TasksSearchResultsSchema
